SET @sql:=IF(EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products_new_inventory_movements' AND INDEX_NAME='pn_im_variation_location_idx'),'SELECT 1','ALTER TABLE `products_new_inventory_movements` ADD INDEX `pn_im_variation_location_idx` (`variation_id`,`location_id`)'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
